  document.addEventListener('input',function(e){
    var el=e.target;
    if(el.id==='item-search'){state.itemSearch=el.value;renderAndFocus('item-search');}
    else if(el.id==='stock-search'){state.stockSearch=el.value;renderAndFocus('stock-search');}
    else if(el.id==='admin-item-search'){document.getElementById('admin-item-list').innerHTML=adminItemList(el.value);}
    else if(el.dataset.bind)state.draft[el.dataset.bind]=el.value;
    else if(el.dataset.qtyIndex!=null){state.draft.lines[Number(el.dataset.qtyIndex)].qty=Number(el.value);}
    else if(el.dataset.manualField){var ml=state.manual.lines[Number(el.dataset.index)];ml[el.dataset.manualField]=el.dataset.manualField==='itemId'?el.value:el.dataset.manualField==='unit'?el.value:Number(el.value);if(el.dataset.manualField==='rate'||el.dataset.manualField==='qty')ml.amount=Number(ml.qty)*Number(ml.rate);}
    else if(el.dataset.reviewField){var rl=state.review.bill.items[Number(el.dataset.index)];rl[el.dataset.reviewField]=el.dataset.reviewField==='itemId'||el.dataset.reviewField==='unit'?el.value:Number(el.value);if(el.dataset.reviewField==='rate'||el.dataset.reviewField==='qty')rl.amount=Number(rl.qty)*Number(rl.rate);}
  });
  document.addEventListener('change',async function(e){
    var el=e.target;
    if(el.id==='work-date'){state.date=el.value||todayISO();resetIssue();syncDraftFromPlates();render();}
    else if(el.id==='stock-category'){state.stockCategory=el.value;render();}
    else if(el.id==='stock-status'){state.stockStatus=el.value;render();}
    else if(el.id==='report-days'){state.reportDays=Number(el.value);render();}
    else if(el.id==='history-type'){state.historyType=el.value;render();}
    else if(el.id==='bill-file')await scanFile(el.files[0],false);
    else if(el.id==='inventory-file')await scanFile(el.files[0],true);
    else if(el.dataset.bind==='receivedBy'){state.draft.receivedBy=el.value;render();}
    else if(el.dataset.manualField==='itemId'){collectManual();var ml=state.manual.lines[Number(el.dataset.index)],it=itemById(el.value);ml.itemId=el.value;ml.unit=it?it.purchaseUnit:'';render();}
    else if(el.dataset.reviewField==='itemId'){captureReviewMeta();var rl=state.review.bill.items[Number(el.dataset.index)],item=itemById(el.value);rl.itemId=el.value;rl.unit=item?item.purchaseUnit:'';rl.flags=(rl.flags||[]).filter(function(f){return f!=='No item match';});render();}
  });
  document.addEventListener('keydown',function(e){
    if(e.key==='Escape'&&modalRoot.innerHTML)closeModal();
    if(e.key==='Tab'&&modalRoot.innerHTML){var focusables=Array.from(modalRoot.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href],summary'));if(!focusables.length)return;var first=focusables[0],last=focusables[focusables.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
  });
